parameters.jsCode:
const items = $input.all();
return items.map(item => {
  const rawDesc = item.json.contentSnippet || item.json.content || item.json.description || '';
  // Extract budget if mentioned in Upwork format
  const budgetMatch = rawDesc.match(/Budget:\s*\$([0-9,]+)/i) || rawDesc.match(/Hourly Range:\s*(\$[0-9.-]+)/i);
  const budget = budgetMatch ? budgetMatch[0] : 'See description';

  return {
    json: {
      title: item.json.title ? item.json.title.replace(/ - Upwork$/i, '').trim() : 'Upwork Lead',
      description: rawDesc,
      source: 'upwork_rss',
      source_job_id: item.json.guid || item.json.link || '',
      budget: budget,
      client_name: 'Upwork Client',
      metadata: {
        link: item.json.link,
        pubDate: item.json.pubDate
      }
    }
  };
});

